"""SQLite-backed order fulfillment service with a JSON CLI."""

from __future__ import annotations

import math
import sqlite3

__all__ = ["OrderError", "OrderService"]

_MAX_SQLITE_INT = 2**63 - 1

_EXPECTED_TABLES = {
    "meta": {"key", "value"},
    "stock": {"sku", "available"},
    "orders": {
        "order_id",
        "idempotency_key",
        "status",
        "total_cents",
        "payment_id",
        "paid_amount_cents",
        "created_at",
        "updated_at",
    },
    "order_items": {"order_id", "sku", "quantity", "unit_price_cents"},
}

_CREATE_STATEMENTS = (
    "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    "INSERT INTO meta (key, value) VALUES ('schema_version', '1')",
    "CREATE TABLE stock ("
    " sku TEXT PRIMARY KEY,"
    " available INTEGER NOT NULL CHECK (available >= 0)"
    ")",
    "CREATE TABLE orders ("
    " order_id TEXT PRIMARY KEY,"
    " idempotency_key TEXT NOT NULL UNIQUE,"
    " status TEXT NOT NULL CHECK (status IN ('pending', 'paid', 'shipped', 'cancelled')),"
    " total_cents INTEGER NOT NULL CHECK (total_cents >= 0),"
    " payment_id TEXT,"
    " paid_amount_cents INTEGER,"
    " created_at BLOB NOT NULL,"
    " updated_at BLOB NOT NULL"
    ")",
    "CREATE UNIQUE INDEX orders_payment_id ON orders (payment_id)"
    " WHERE payment_id IS NOT NULL",
    "CREATE TABLE order_items ("
    " order_id TEXT NOT NULL REFERENCES orders (order_id),"
    " sku TEXT NOT NULL,"
    " quantity INTEGER NOT NULL CHECK (quantity > 0),"
    " unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),"
    " PRIMARY KEY (order_id, sku)"
    ")",
)


class OrderError(Exception):
    """Stable order-domain error with a machine-readable code."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = str(code)
        self.message = str(message)
        self.details = dict(details) if details is not None else {}

    def __str__(self) -> str:
        return self.message


def _invalid(message, **details):
    return OrderError("INVALID_INPUT", message, details)


def _require_key_string(value, field):
    if not isinstance(value, str) or not value.strip():
        raise _invalid(f"{field} must be a non-empty string", field=field)
    return value


def _require_int(value, field, minimum):
    if isinstance(value, bool) or not isinstance(value, int):
        raise _invalid(f"{field} must be an integer", field=field)
    if value < minimum:
        raise _invalid(f"{field} must be >= {minimum}", field=field)
    if value > _MAX_SQLITE_INT:
        raise _invalid(f"{field} is too large", field=field)
    return value


def _validate_items(items):
    if not isinstance(items, list) or not items:
        raise _invalid("items must be a non-empty list", field="items")
    canonical = []
    seen = set()
    for index, item in enumerate(items):
        label = f"items[{index}]"
        if not isinstance(item, dict):
            raise _invalid(f"{label} must be an object", field=label)
        if set(item) != {"sku", "quantity", "unit_price_cents"}:
            raise _invalid(
                f"{label} must have exactly sku, quantity, unit_price_cents",
                field=label,
            )
        sku = _require_key_string(item["sku"], f"{label}.sku")
        quantity = _require_int(item["quantity"], f"{label}.quantity", 1)
        unit_price = _require_int(item["unit_price_cents"], f"{label}.unit_price_cents", 0)
        if sku in seen:
            raise _invalid("duplicate sku in items", sku=sku)
        seen.add(sku)
        canonical.append((sku, quantity, unit_price))
    canonical.sort(key=lambda entry: entry[0])
    total = 0
    for _, quantity, unit_price in canonical:
        total += quantity * unit_price
    if total > _MAX_SQLITE_INT:
        raise _invalid("order total is too large", field="items")
    return canonical, total


class OrderService:
    """SQLite-backed order service safe for concurrent multi-instance use."""

    def __init__(self, db_path, *, clock, id_factory):
        if not callable(clock):
            raise OrderError(
                "INVALID_DEPENDENCY", "clock must be callable", {"dependency": "clock"}
            )
        if not callable(id_factory):
            raise OrderError(
                "INVALID_DEPENDENCY",
                "id_factory must be callable",
                {"dependency": "id_factory"},
            )
        self._db_path = db_path
        self._clock = clock
        self._id_factory = id_factory
        self._mem_con = None
        if isinstance(db_path, str) and ":memory:" in db_path:
            self._mem_con = self._connect()
        self._run(self._ensure_schema, write=True)

    # ------------------------------------------------------------------
    # infrastructure
    # ------------------------------------------------------------------

    def _connect(self):
        try:
            con = sqlite3.connect(self._db_path, timeout=30.0, isolation_level=None)
        except TypeError as exc:
            raise _invalid("db_path is not acceptable to sqlite3.connect", reason=str(exc)) from exc
        except OverflowError as exc:
            raise _invalid("db_path is not acceptable to sqlite3.connect", reason=str(exc)) from exc
        except sqlite3.Error as exc:
            raise OrderError(
                "STORAGE_ERROR", "cannot open database", {"reason": str(exc)}
            ) from exc
        try:
            con.execute("PRAGMA foreign_keys = ON")
        except sqlite3.Error as exc:
            con.close()
            raise OrderError(
                "STORAGE_ERROR", "cannot configure database", {"reason": str(exc)}
            ) from exc
        return con

    def _acquire(self):
        if self._mem_con is not None:
            return self._mem_con
        return self._connect()

    def _release(self, con):
        if con is not self._mem_con:
            con.close()

    def _run(self, operation, *, write):
        con = self._acquire()
        try:
            try:
                con.execute("BEGIN IMMEDIATE" if write else "BEGIN")
                result = operation(con)
                con.execute("COMMIT")
                return result
            except BaseException:
                try:
                    con.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                raise
        except OrderError:
            raise
        except sqlite3.Error as exc:
            raise OrderError("STORAGE_ERROR", "storage failure", {"reason": str(exc)}) from exc
        finally:
            self._release(con)

    def _ensure_schema(self, con):
        tables = {
            row[0]
            for row in con.execute(
                "SELECT name FROM sqlite_master"
                " WHERE type = 'table' AND name NOT LIKE 'sqlite_%'"
            )
        }
        if not tables:
            for statement in _CREATE_STATEMENTS:
                con.execute(statement)
            return None
        for name, columns in _EXPECTED_TABLES.items():
            if name not in tables:
                raise OrderError(
                    "SCHEMA_MISMATCH", f"missing table {name}", {"table": name}
                )
            found = {row[1] for row in con.execute(f"PRAGMA table_info({name})")}
            if found != columns:
                raise OrderError(
                    "SCHEMA_MISMATCH", f"unexpected columns in table {name}", {"table": name}
                )
        unknown = tables - set(_EXPECTED_TABLES)
        if unknown:
            raise OrderError(
                "SCHEMA_MISMATCH", "unknown tables present", {"tables": sorted(unknown)}
            )
        row = con.execute("SELECT value FROM meta WHERE key = 'schema_version'").fetchone()
        if row is None or row[0] != "1":
            raise OrderError(
                "SCHEMA_MISMATCH",
                "unsupported schema version",
                {"schema_version": None if row is None else row[0]},
            )
        return None

    def _clock_now(self):
        try:
            value = self._clock()
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError(
                "INVALID_DEPENDENCY",
                "clock raised an exception",
                {"dependency": "clock", "reason": str(exc)},
            ) from exc
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise OrderError(
                "INVALID_DEPENDENCY",
                "clock must return a finite number",
                {"dependency": "clock"},
            )
        try:
            finite = math.isfinite(value)
        except OverflowError:
            finite = False
        if not finite:
            raise OrderError(
                "INVALID_DEPENDENCY",
                "clock must return a finite number",
                {"dependency": "clock"},
            )
        return value

    def _new_order_id(self):
        try:
            value = self._id_factory()
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError(
                "INVALID_DEPENDENCY",
                "id_factory raised an exception",
                {"dependency": "id_factory", "reason": str(exc)},
            ) from exc
        if not isinstance(value, str) or not value.strip():
            raise OrderError(
                "INVALID_DEPENDENCY",
                "id_factory must return a non-empty string",
                {"dependency": "id_factory"},
            )
        return value

    def _load_order(self, con, order_id):
        row = con.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id,"
            " created_at, updated_at FROM orders WHERE order_id = ?",
            (order_id,),
        ).fetchone()
        if row is None:
            raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
        items = [
            {"sku": sku, "quantity": quantity, "unit_price_cents": unit_price}
            for sku, quantity, unit_price in con.execute(
                "SELECT sku, quantity, unit_price_cents FROM order_items"
                " WHERE order_id = ? ORDER BY sku",
                (order_id,),
            ).fetchall()
        ]
        return {
            "order_id": row[0],
            "idempotency_key": row[1],
            "status": row[2],
            "items": items,
            "total_cents": row[3],
            "payment_id": row[4],
            "created_at": row[5],
            "updated_at": row[6],
        }

    # ------------------------------------------------------------------
    # public API
    # ------------------------------------------------------------------

    def set_stock(self, sku: str, quantity: int) -> dict:
        _require_key_string(sku, "sku")
        _require_int(quantity, "quantity", 0)

        def operation(con):
            con.execute(
                "INSERT INTO stock (sku, available) VALUES (?, ?)"
                " ON CONFLICT (sku) DO UPDATE SET available = excluded.available",
                (sku, quantity),
            )
            return {"sku": sku, "available": quantity}

        return self._run(operation, write=True)

    def create_order(self, idempotency_key: str, items: list[dict]) -> dict:
        _require_key_string(idempotency_key, "idempotency_key")
        canonical, total = _validate_items(items)

        def operation(con):
            row = con.execute(
                "SELECT order_id FROM orders WHERE idempotency_key = ?",
                (idempotency_key,),
            ).fetchone()
            if row is not None:
                existing = self._load_order(con, row[0])
                stored = [
                    (item["sku"], item["quantity"], item["unit_price_cents"])
                    for item in existing["items"]
                ]
                if stored == canonical:
                    return existing
                raise OrderError(
                    "IDEMPOTENCY_CONFLICT",
                    "idempotency key was already used with different items",
                    {"idempotency_key": idempotency_key},
                )
            insufficient = []
            for sku, quantity, _ in canonical:
                stock_row = con.execute(
                    "SELECT available FROM stock WHERE sku = ?", (sku,)
                ).fetchone()
                if stock_row is None or stock_row[0] < quantity:
                    insufficient.append(sku)
            if insufficient:
                raise OrderError(
                    "INSUFFICIENT_STOCK",
                    "insufficient stock for one or more skus",
                    {"skus": insufficient},
                )
            order_id = None
            for _ in range(3):
                candidate = self._new_order_id()
                exists = con.execute(
                    "SELECT 1 FROM orders WHERE order_id = ?", (candidate,)
                ).fetchone()
                if exists is None:
                    order_id = candidate
                    break
            if order_id is None:
                raise OrderError(
                    "ID_COLLISION",
                    "id_factory produced duplicate order ids",
                    {"attempts": 3},
                )
            now = self._clock_now()
            con.execute(
                "INSERT INTO orders (order_id, idempotency_key, status, total_cents,"
                " payment_id, paid_amount_cents, created_at, updated_at)"
                " VALUES (?, ?, 'pending', ?, NULL, NULL, ?, ?)",
                (order_id, idempotency_key, total, now, now),
            )
            for sku, quantity, unit_price in canonical:
                con.execute(
                    "INSERT INTO order_items (order_id, sku, quantity, unit_price_cents)"
                    " VALUES (?, ?, ?, ?)",
                    (order_id, sku, quantity, unit_price),
                )
                cursor = con.execute(
                    "UPDATE stock SET available = available - ?"
                    " WHERE sku = ? AND available >= ?",
                    (quantity, sku, quantity),
                )
                if cursor.rowcount != 1:
                    raise OrderError(
                        "INSUFFICIENT_STOCK",
                        "insufficient stock for one or more skus",
                        {"skus": [sku]},
                    )
            return self._load_order(con, order_id)

        return self._run(operation, write=True)

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict:
        _require_key_string(order_id, "order_id")
        _require_key_string(payment_id, "payment_id")
        _require_int(amount_cents, "amount_cents", 0)

        def operation(con):
            row = con.execute(
                "SELECT status, total_cents, payment_id, paid_amount_cents"
                " FROM orders WHERE order_id = ?",
                (order_id,),
            ).fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
            status, total, recorded_payment, recorded_amount = row
            if recorded_payment is not None:
                if payment_id == recorded_payment and amount_cents == recorded_amount:
                    return self._load_order(con, order_id)
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    "payment does not match the recorded payment for this order",
                    {"order_id": order_id},
                )
            if status != "pending":
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot pay an order in status {status}",
                    {"order_id": order_id, "status": status},
                )
            other = con.execute(
                "SELECT order_id FROM orders WHERE payment_id = ? AND order_id <> ?",
                (payment_id, order_id),
            ).fetchone()
            if other is not None:
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    "payment_id was already used for another order",
                    {"payment_id": payment_id},
                )
            if amount_cents != total:
                raise OrderError(
                    "AMOUNT_MISMATCH",
                    "amount_cents must equal the order total_cents",
                    {"expected": total, "received": amount_cents},
                )
            now = self._clock_now()
            con.execute(
                "UPDATE orders SET status = 'paid', payment_id = ?,"
                " paid_amount_cents = ?, updated_at = ? WHERE order_id = ?",
                (payment_id, amount_cents, now, order_id),
            )
            return self._load_order(con, order_id)

        return self._run(operation, write=True)

    def cancel_order(self, order_id: str) -> dict:
        _require_key_string(order_id, "order_id")

        def operation(con):
            row = con.execute(
                "SELECT status FROM orders WHERE order_id = ?", (order_id,)
            ).fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
            status = row[0]
            if status == "cancelled":
                return self._load_order(con, order_id)
            if status == "shipped":
                raise OrderError(
                    "INVALID_STATE",
                    "a shipped order cannot be cancelled",
                    {"order_id": order_id, "status": status},
                )
            now = self._clock_now()
            reserved = con.execute(
                "SELECT sku, quantity FROM order_items WHERE order_id = ?",
                (order_id,),
            ).fetchall()
            for sku, quantity in reserved:
                con.execute(
                    "INSERT INTO stock (sku, available) VALUES (?, ?)"
                    " ON CONFLICT (sku) DO UPDATE"
                    " SET available = stock.available + excluded.available",
                    (sku, quantity),
                )
            con.execute(
                "UPDATE orders SET status = 'cancelled', updated_at = ?"
                " WHERE order_id = ?",
                (now, order_id),
            )
            return self._load_order(con, order_id)

        return self._run(operation, write=True)

    def ship_order(self, order_id: str) -> dict:
        _require_key_string(order_id, "order_id")

        def operation(con):
            row = con.execute(
                "SELECT status FROM orders WHERE order_id = ?", (order_id,)
            ).fetchone()
            if row is None:
                raise OrderError("NOT_FOUND", "order not found", {"order_id": order_id})
            status = row[0]
            if status == "shipped":
                return self._load_order(con, order_id)
            if status != "paid":
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot ship an order in status {status}",
                    {"order_id": order_id, "status": status},
                )
            now = self._clock_now()
            con.execute(
                "UPDATE orders SET status = 'shipped', updated_at = ?"
                " WHERE order_id = ?",
                (now, order_id),
            )
            return self._load_order(con, order_id)

        return self._run(operation, write=True)

    def get_order(self, order_id: str) -> dict:
        _require_key_string(order_id, "order_id")

        def operation(con):
            return self._load_order(con, order_id)

        return self._run(operation, write=False)

