"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time
import uuid

from . import OrderError, OrderService

_COMMANDS = {
    "stock": ("sku", "quantity"),
    "create": ("idempotency_key", "items"),
    "pay": ("order_id", "payment_id", "amount_cents"),
    "cancel": ("order_id",),
    "ship": ("order_id",),
    "get": ("order_id",),
}

_EXIT_STORAGE_CODES = {"STORAGE_ERROR"}


class _CliError(Exception):
    def __init__(self, code, message, details, exit_code):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = details
        self.exit_code = exit_code


def _emit(payload) -> None:
    text = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )
    sys.stdout.buffer.write(text.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()


def _reject_constant(name):
    raise ValueError(f"unsupported JSON constant: {name}")


def _read_request() -> dict:
    raw = sys.stdin.buffer.read()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise _CliError("INVALID_INPUT", "stdin must be UTF-8 text", {}, 2) from None
    lines = [line for line in text.splitlines() if line.strip()]
    if len(lines) != 1:
        raise _CliError(
            "INVALID_INPUT",
            "expected exactly one non-empty JSON line on stdin",
            {"non_empty_lines": len(lines)},
            2,
        )
    try:
        value = json.loads(lines[0], parse_constant=_reject_constant)
    except ValueError:
        raise _CliError("INVALID_INPUT", "stdin is not valid JSON", {}, 2) from None
    if not isinstance(value, dict):
        raise _CliError("INVALID_INPUT", "input must be a JSON object", {}, 2)
    return value


def _check_fields(request, required) -> None:
    missing = [field for field in required if field not in request]
    unknown = [field for field in request if field not in required]
    if missing or unknown:
        raise _CliError(
            "INVALID_INPUT",
            "input object has missing or unknown fields",
            {"missing": missing, "unknown": unknown},
            2,
        )


def main(argv=None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        if len(args) != 3 or args[0] != "--db":
            raise _CliError(
                "INVALID_INPUT",
                "usage: python -m src.order_fulfillment --db <path> <command>",
                {},
                2,
            )
        db_path, command = args[1], args[2]
        if command not in _COMMANDS:
            raise _CliError("INVALID_INPUT", "unknown command", {"command": command}, 2)
        request = _read_request()
        _check_fields(request, _COMMANDS[command])
        service = OrderService(
            db_path, clock=time.time, id_factory=lambda: uuid.uuid4().hex
        )
        if command == "stock":
            result = service.set_stock(request["sku"], request["quantity"])
        elif command == "create":
            result = service.create_order(request["idempotency_key"], request["items"])
        elif command == "pay":
            result = service.pay_order(
                request["order_id"], request["payment_id"], request["amount_cents"]
            )
        elif command == "cancel":
            result = service.cancel_order(request["order_id"])
        elif command == "ship":
            result = service.ship_order(request["order_id"])
        else:
            result = service.get_order(request["order_id"])
    except _CliError as exc:
        _emit({"ok": False, "error": {"code": exc.code, "message": exc.message, "details": exc.details}})
        return exc.exit_code
    except OrderError as exc:
        _emit({"ok": False, "error": {"code": exc.code, "message": exc.message, "details": exc.details}})
        return 3 if exc.code in _EXIT_STORAGE_CODES else 2
    except Exception:
        _emit(
            {
                "ok": False,
                "error": {
                    "code": "STORAGE_ERROR",
                    "message": "unexpected internal failure",
                    "details": {},
                },
            }
        )
        return 3
    _emit({"ok": True, "result": result})
    return 0


if __name__ == "__main__":
    sys.exit(main())

