"""Filesystem-backed durable delivery spool with lease-based claims."""

from __future__ import annotations

import hmac
import json
import math
import os
import secrets
import time
from dataclasses import dataclass

__all__ = ["Limits", "Spool", "SpoolError"]

_STATE_NAME = "state.json"
_LOCK_NAME = "state.lock"
_STATUSES = ("pending", "leased", "acked", "dead")
_TOP_KEYS = {"messages", "next_sequence", "schema_version"}
_BASE_KEYS = {"attempts", "available_at", "last_error", "payload", "sequence", "status"}
_LEASE_KEYS = {"expires_at", "lease_token", "worker_id"}
_LEASE_FIELDS = ("expires_at", "lease_token", "worker_id")
_O_BINARY = getattr(os, "O_BINARY", 0)


@dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error with a machine-readable code."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = str(code)
        self.message = str(message)
        self.details = dict(details) if details is not None else {}

    def __str__(self) -> str:
        return self.message


def _invalid(message, **details):
    return SpoolError("INVALID_INPUT", message, details)


def _corrupt(message, **details):
    return SpoolError("CORRUPT_STATE", message, details)


def _is_number(value) -> bool:
    return not isinstance(value, bool) and isinstance(value, (int, float))


def _is_finite_number(value) -> bool:
    if not _is_number(value):
        return False
    try:
        return math.isfinite(value)
    except OverflowError:
        return False


def _canonical_text(value) -> str:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )


def _require_id(value, field) -> str:
    if not isinstance(value, str) or not value.strip():
        raise _invalid(f"{field} must be a non-empty string", field=field)
    return value


def _require_token(value) -> str:
    if not isinstance(value, str):
        raise _invalid("lease_token must be a string", field="lease_token")
    return value


def _validate_limits(limits) -> None:
    for field in ("max_messages", "max_payload_bytes", "max_attempts"):
        value = getattr(limits, field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 1:
            raise _invalid(f"{field} must be a positive integer", field=field)
    for field in ("lease_seconds", "retry_delay"):
        value = getattr(limits, field)
        if not _is_finite_number(value) or value < 0:
            raise _invalid(f"{field} must be a finite number >= 0", field=field)
    if limits.lease_seconds <= 0:
        raise _invalid("lease_seconds must be > 0", field="lease_seconds")


def _validate_payload_value(value, path) -> None:
    if value is None or isinstance(value, (bool, str)):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise _invalid("payload numbers must be finite", path=path)
        return
    if isinstance(value, list):
        for index, entry in enumerate(value):
            _validate_payload_value(entry, f"{path}[{index}]")
        return
    if isinstance(value, dict):
        for key, entry in value.items():
            if not isinstance(key, str):
                raise _invalid("payload object keys must be strings", path=path)
            _validate_payload_value(entry, f"{path}.{key}")
        return
    raise _invalid("payload must contain only JSON types", path=path)


def _canonical_payload(payload, max_payload_bytes) -> str:
    try:
        json.dumps(payload, allow_nan=False)
    except (TypeError, ValueError, RecursionError) as exc:
        raise _invalid("payload is not JSON-serializable", reason=str(exc)) from exc
    _validate_payload_value(payload, "payload")
    text = _canonical_text(payload)
    size = len(text.encode("utf-8"))
    if size > max_payload_bytes:
        raise _invalid(
            "payload exceeds max_payload_bytes",
            max_payload_bytes=max_payload_bytes,
            size=size,
        )
    return text


def _reject_duplicate_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key!r}")
        result[key] = value
    return result


def _reject_json_constant(name):
    raise ValueError(f"unsupported JSON constant: {name}")


def _validate_state(state) -> None:
    if not isinstance(state, dict):
        raise _corrupt("state root must be a JSON object")
    if set(state) != _TOP_KEYS:
        raise _corrupt("state has missing or unknown top-level fields")
    version = state["schema_version"]
    if isinstance(version, bool) or not isinstance(version, int):
        raise _corrupt("schema_version must be an integer")
    if version != 1:
        raise SpoolError(
            "SCHEMA_MISMATCH",
            "unsupported schema_version",
            {"schema_version": version},
        )
    next_sequence = state["next_sequence"]
    if isinstance(next_sequence, bool) or not isinstance(next_sequence, int) or next_sequence < 1:
        raise _corrupt("next_sequence must be an integer >= 1")
    messages = state["messages"]
    if not isinstance(messages, dict):
        raise _corrupt("messages must be a JSON object")
    seen_sequences = set()
    for message_id, record in messages.items():
        if not isinstance(message_id, str) or not message_id.strip():
            raise _corrupt("message ids must be non-empty strings")
        if not isinstance(record, dict):
            raise _corrupt("message records must be JSON objects")
        status = record.get("status")
        if status not in _STATUSES:
            raise _corrupt("message status is invalid", message_id=message_id)
        expected_keys = _BASE_KEYS | (_LEASE_KEYS if status == "leased" else set())
        if set(record) != expected_keys:
            raise _corrupt(
                "message record fields are inconsistent with its status",
                message_id=message_id,
            )
        if not _is_finite_number(record["available_at"]):
            raise _corrupt("available_at must be a finite number", message_id=message_id)
        sequence = record["sequence"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise _corrupt("sequence must be an integer >= 1", message_id=message_id)
        if sequence >= next_sequence:
            raise _corrupt("sequence conflicts with next_sequence", message_id=message_id)
        if sequence in seen_sequences:
            raise _corrupt("duplicate sequence", message_id=message_id)
        seen_sequences.add(sequence)
        attempts = record["attempts"]
        if isinstance(attempts, bool) or not isinstance(attempts, int) or attempts < 0:
            raise _corrupt("attempts must be an integer >= 0", message_id=message_id)
        last_error = record["last_error"]
        if last_error is not None and not isinstance(last_error, str):
            raise _corrupt("last_error must be null or a string", message_id=message_id)
        if status == "leased":
            if not _is_finite_number(record["expires_at"]):
                raise _corrupt("expires_at must be a finite number", message_id=message_id)
            lease_token = record["lease_token"]
            if not isinstance(lease_token, str) or not lease_token:
                raise _corrupt("lease_token must be a non-empty string", message_id=message_id)
            worker_id = record["worker_id"]
            if not isinstance(worker_id, str) or not worker_id.strip():
                raise _corrupt("worker_id must be a non-empty string", message_id=message_id)


def _public_message(message_id, record) -> dict:
    return {
        "message_id": message_id,
        "payload": record["payload"],
        "status": record["status"],
        "available_at": record["available_at"],
        "sequence": record["sequence"],
        "attempts": record["attempts"],
        "last_error": record["last_error"],
    }


class Spool:
    """Durable filesystem outbox/lease queue rooted at a single directory."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        try:
            root_path = os.fspath(root)
        except TypeError as exc:
            raise _invalid("root must be a filesystem path", reason=str(exc)) from exc
        if isinstance(root_path, bytes):
            try:
                root_path = os.fsdecode(root_path)
            except (UnicodeError, ValueError) as exc:
                raise _invalid("root must decode to a filesystem path", reason=str(exc)) from exc
        if not isinstance(root_path, str) or not root_path.strip():
            raise _invalid("root must be a non-empty path", field="root")
        if not callable(clock):
            raise SpoolError(
                "INVALID_DEPENDENCY", "clock must be callable", {"dependency": "clock"}
            )
        if not isinstance(limits, Limits):
            raise _invalid("limits must be a Limits instance", field="limits")
        _validate_limits(limits)
        if not _is_finite_number(lock_timeout) or lock_timeout < 0:
            raise _invalid("lock_timeout must be a finite number >= 0", field="lock_timeout")
        if failpoint is not None and not callable(failpoint):
            raise _invalid("failpoint must be None or callable", field="failpoint")
        self._root = root_path
        self._clock = clock
        self._limits = limits
        self._lock_timeout = float(lock_timeout)
        self._failpoint = failpoint

    # ------------------------------------------------------------------
    # infrastructure
    # ------------------------------------------------------------------

    def _fire_failpoint(self, name) -> None:
        if self._failpoint is not None:
            self._failpoint(name)

    def _clock_now(self):
        try:
            value = self._clock()
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError(
                "INVALID_DEPENDENCY",
                "clock raised an exception",
                {"dependency": "clock", "reason": str(exc)},
            ) from exc
        if not _is_finite_number(value):
            raise SpoolError(
                "INVALID_DEPENDENCY",
                "clock must return a finite number",
                {"dependency": "clock"},
            )
        return value

    def _acquire_lock(self) -> str:
        lock_path = os.path.join(self._root, _LOCK_NAME)
        deadline = time.monotonic() + self._lock_timeout
        while True:
            try:
                fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY | _O_BINARY)
            except FileExistsError:
                if time.monotonic() >= deadline:
                    raise SpoolError(
                        "LOCK_TIMEOUT",
                        "could not acquire the state lock in time",
                        {"lock": _LOCK_NAME},
                    ) from None
                time.sleep(0.005)
                continue
            except FileNotFoundError as exc:
                raise SpoolError(
                    "NOT_INITIALIZED",
                    "spool root does not exist",
                    {"root": self._root},
                ) from exc
            except OSError as exc:
                raise SpoolError(
                    "INTERNAL_ERROR", "cannot acquire the state lock", {"reason": str(exc)}
                ) from exc
            os.close(fd)
            return lock_path

    def _locked(self, operation, *, for_init=False):
        if not for_init and not os.path.isdir(self._root):
            raise SpoolError(
                "NOT_INITIALIZED", "spool is not initialized", {"root": self._root}
            )
        lock_path = self._acquire_lock()
        tmp_paths: list[str] = []
        try:
            self._fire_failpoint("after_lock")
            return operation(tmp_paths)
        finally:
            for tmp_path in tmp_paths:
                try:
                    os.unlink(tmp_path)
                except OSError:
                    pass
            try:
                os.unlink(lock_path)
            except OSError:
                pass

    def _read_state(self):
        state_path = os.path.join(self._root, _STATE_NAME)
        try:
            with open(state_path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError as exc:
            raise SpoolError(
                "NOT_INITIALIZED", "spool is not initialized", {"root": self._root}
            ) from exc
        except OSError as exc:
            raise SpoolError(
                "INTERNAL_ERROR", "cannot read state", {"reason": str(exc)}
            ) from exc
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise _corrupt("state is not valid UTF-8", reason=str(exc)) from exc
        try:
            state = json.loads(
                text,
                object_pairs_hook=_reject_duplicate_keys,
                parse_constant=_reject_json_constant,
            )
        except ValueError as exc:
            raise _corrupt("state is not valid JSON", reason=str(exc)) from exc
        _validate_state(state)
        if raw != (_canonical_text(state) + "\n").encode("utf-8"):
            raise _corrupt("state is not canonical JSON")
        return state

    def _commit(self, state, tmp_paths) -> None:
        data = (_canonical_text(state) + "\n").encode("utf-8")
        tmp_path = os.path.join(
            self._root, f".state.{os.getpid()}.{secrets.token_hex(8)}.tmp"
        )
        tmp_paths.append(tmp_path)
        try:
            fd = os.open(tmp_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY | _O_BINARY)
            with os.fdopen(fd, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
        except OSError as exc:
            raise SpoolError(
                "INTERNAL_ERROR", "cannot write state", {"reason": str(exc)}
            ) from exc
        self._fire_failpoint("before_replace")
        try:
            os.replace(tmp_path, os.path.join(self._root, _STATE_NAME))
        except OSError as exc:
            raise SpoolError(
                "INTERNAL_ERROR", "cannot publish state", {"reason": str(exc)}
            ) from exc
        self._fire_failpoint("after_replace")
        try:
            dir_fd = os.open(self._root, os.O_RDONLY)
        except OSError:
            return
        try:
            os.fsync(dir_fd)
        except OSError:
            pass
        finally:
            os.close(dir_fd)

    # ------------------------------------------------------------------
    # public API
    # ------------------------------------------------------------------

    def initialize(self) -> dict:
        try:
            os.makedirs(self._root, exist_ok=True)
        except OSError as exc:
            raise SpoolError(
                "INTERNAL_ERROR", "cannot create spool root", {"reason": str(exc)}
            ) from exc

        def operation(tmp_paths):
            state_path = os.path.join(self._root, _STATE_NAME)
            if os.path.exists(state_path):
                self._read_state()
                raise SpoolError(
                    "ALREADY_INITIALIZED",
                    "spool root already contains a state",
                    {"root": self._root},
                )
            state = {"schema_version": 1, "next_sequence": 1, "messages": {}}
            self._commit(state, tmp_paths)
            return {"schema_version": 1, "next_sequence": 1, "messages": {}}

        return self._locked(operation, for_init=True)

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        _require_id(message_id, "message_id")
        canonical_payload = _canonical_payload(payload, self._limits.max_payload_bytes)
        if available_at is not None and not _is_finite_number(available_at):
            raise _invalid("available_at must be a finite number", field="available_at")

        def operation(tmp_paths):
            state = self._read_state()
            messages = state["messages"]
            existing = messages.get(message_id)
            if existing is not None:
                same_payload = _canonical_text(existing["payload"]) == canonical_payload
                same_available = (
                    available_at is None or existing["available_at"] == available_at
                )
                if same_payload and same_available:
                    return _public_message(message_id, existing)
                raise SpoolError(
                    "IDEMPOTENCY_CONFLICT",
                    "message_id was already used with a different request",
                    {"message_id": message_id},
                )
            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    "max_messages reached",
                    {"max_messages": self._limits.max_messages},
                )
            effective_available = (
                available_at if available_at is not None else self._clock_now()
            )
            record = {
                "attempts": 0,
                "available_at": effective_available,
                "last_error": None,
                "payload": json.loads(canonical_payload),
                "sequence": state["next_sequence"],
                "status": "pending",
            }
            state["next_sequence"] += 1
            messages[message_id] = record
            self._commit(state, tmp_paths)
            return _public_message(message_id, record)

        return self._locked(operation)

    def claim(self, worker_id: str) -> dict | None:
        _require_id(worker_id, "worker_id")

        def operation(tmp_paths):
            state = self._read_state()
            now = self._clock_now()
            best = None
            for message_id, record in state["messages"].items():
                if record["status"] != "pending" or record["available_at"] > now:
                    continue
                order_key = (record["available_at"], record["sequence"], message_id)
                if best is None or order_key < best[0]:
                    best = (order_key, message_id, record)
            if best is None:
                return None
            _, message_id, record = best
            record["status"] = "leased"
            record["attempts"] += 1
            record["worker_id"] = worker_id
            record["lease_token"] = secrets.token_hex(16)
            record["expires_at"] = now + self._limits.lease_seconds
            self._commit(state, tmp_paths)
            result = _public_message(message_id, record)
            result["lease_token"] = record["lease_token"]
            return result

        return self._locked(operation)

    def ack(self, message_id: str, lease_token: str) -> dict:
        _require_id(message_id, "message_id")
        _require_token(lease_token)

        def operation(tmp_paths):
            state = self._read_state()
            record = state["messages"].get(message_id)
            if record is None:
                raise SpoolError(
                    "NOT_FOUND", "unknown message_id", {"message_id": message_id}
                )
            if record["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    "message is not currently leased",
                    {"message_id": message_id, "status": record["status"]},
                )
            if not hmac.compare_digest(
                record["lease_token"].encode("utf-8"), lease_token.encode("utf-8")
            ):
                raise SpoolError(
                    "UNAUTHORIZED", "lease token mismatch", {"message_id": message_id}
                )
            record["status"] = "acked"
            for field in _LEASE_FIELDS:
                record.pop(field, None)
            self._commit(state, tmp_paths)
            return _public_message(message_id, record)

        return self._locked(operation)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        _require_id(message_id, "message_id")
        _require_token(lease_token)
        if not isinstance(error, str) or not error:
            raise _invalid("error must be a non-empty string", field="error")

        def operation(tmp_paths):
            state = self._read_state()
            record = state["messages"].get(message_id)
            if record is None:
                raise SpoolError(
                    "NOT_FOUND", "unknown message_id", {"message_id": message_id}
                )
            if record["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    "message is not currently leased",
                    {"message_id": message_id, "status": record["status"]},
                )
            if not hmac.compare_digest(
                record["lease_token"].encode("utf-8"), lease_token.encode("utf-8")
            ):
                raise SpoolError(
                    "UNAUTHORIZED", "lease token mismatch", {"message_id": message_id}
                )
            for field in _LEASE_FIELDS:
                record.pop(field, None)
            record["last_error"] = error
            if record["attempts"] >= self._limits.max_attempts:
                record["status"] = "dead"
            else:
                record["status"] = "pending"
                record["available_at"] = self._clock_now() + self._limits.retry_delay
            self._commit(state, tmp_paths)
            return _public_message(message_id, record)

        return self._locked(operation)

    def recover(self) -> dict:
        def operation(tmp_paths):
            state = self._read_state()
            now = self._clock_now()
            recovered = 0
            for record in state["messages"].values():
                if record["status"] != "leased":
                    continue
                if now < record["expires_at"]:
                    continue
                for field in _LEASE_FIELDS:
                    record.pop(field, None)
                if record["attempts"] >= self._limits.max_attempts:
                    record["status"] = "dead"
                else:
                    record["status"] = "pending"
                    record["available_at"] = now
                recovered += 1
            if recovered:
                self._commit(state, tmp_paths)
            return {"recovered": recovered}

        return self._locked(operation)

    def get(self, message_id: str) -> dict:
        _require_id(message_id, "message_id")

        def operation(tmp_paths):
            state = self._read_state()
            record = state["messages"].get(message_id)
            if record is None:
                raise SpoolError(
                    "NOT_FOUND", "unknown message_id", {"message_id": message_id}
                )
            return _public_message(message_id, record)

        return self._locked(operation)

    def list_messages(self, status=None) -> list[dict]:
        if status is not None and status not in _STATUSES:
            raise _invalid(
                "status must be one of pending, leased, acked, dead", status=status
            )

        def operation(tmp_paths):
            state = self._read_state()
            selected = [
                (record["available_at"], record["sequence"], message_id, record)
                for message_id, record in state["messages"].items()
                if status is None or record["status"] == status
            ]
            selected.sort(key=lambda entry: (entry[0], entry[1], entry[2]))
            return [
                _public_message(message_id, record)
                for _, _, message_id, record in selected
            ]

        return self._locked(operation)

