"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time

from . import Limits, Spool, SpoolError

# command -> (required fields, optional fields, empty stdin allowed)
_COMMANDS = {
    "init": ((), (), True),
    "enqueue": (("message_id", "payload"), ("available_at",), False),
    "claim": (("worker_id",), (), False),
    "ack": (("message_id", "lease_token"), (), False),
    "fail": (("message_id", "lease_token", "error"), (), False),
    "recover": ((), (), True),
    "show": (("message_id",), (), False),
    "list": ((), ("status",), True),
}

_EXIT_INTERNAL_CODES = {"CORRUPT_STATE", "LOCK_TIMEOUT", "INTERNAL_ERROR"}


class _CliError(Exception):
    def __init__(self, code, message, details, exit_code):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = details
        self.exit_code = exit_code


def _emit(payload) -> None:
    text = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    )
    sys.stdout.buffer.write(text.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()


def _reject_constant(name):
    raise ValueError(f"unsupported JSON constant: {name}")


def _read_request(empty_ok) -> dict:
    raw = sys.stdin.buffer.read()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise _CliError("INVALID_INPUT", "stdin must be UTF-8 text", {}, 2) from None
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines and empty_ok:
        return {}
    if len(lines) != 1:
        raise _CliError(
            "INVALID_INPUT",
            "expected exactly one non-empty JSON line on stdin",
            {"non_empty_lines": len(lines)},
            2,
        )
    try:
        value = json.loads(lines[0], parse_constant=_reject_constant)
    except ValueError:
        raise _CliError("INVALID_INPUT", "stdin is not valid JSON", {}, 2) from None
    if not isinstance(value, dict):
        raise _CliError("INVALID_INPUT", "input must be a JSON object", {}, 2)
    return value


def _check_fields(request, required, optional) -> None:
    allowed = set(required) | set(optional)
    missing = [field for field in required if field not in request]
    unknown = [field for field in request if field not in allowed]
    if missing or unknown:
        raise _CliError(
            "INVALID_INPUT",
            "input object has missing or unknown fields",
            {"missing": missing, "unknown": unknown},
            2,
        )


def main(argv=None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        if len(args) != 3 or args[0] != "--root":
            raise _CliError(
                "INVALID_INPUT",
                "usage: python -m src.delivery_spool --root <path> <command>",
                {},
                2,
            )
        root, command = args[1], args[2]
        if command not in _COMMANDS:
            raise _CliError("INVALID_INPUT", "unknown command", {"command": command}, 2)
        required, optional, empty_ok = _COMMANDS[command]
        request = _read_request(empty_ok)
        _check_fields(request, required, optional)
        spool = Spool(
            root, clock=time.time, limits=Limits(), lock_timeout=10.0, failpoint=None
        )
        if command == "init":
            result = spool.initialize()
        elif command == "enqueue":
            result = spool.enqueue(
                request["message_id"],
                request["payload"],
                request.get("available_at"),
            )
        elif command == "claim":
            result = spool.claim(request["worker_id"])
        elif command == "ack":
            result = spool.ack(request["message_id"], request["lease_token"])
        elif command == "fail":
            result = spool.fail(
                request["message_id"], request["lease_token"], request["error"]
            )
        elif command == "recover":
            result = spool.recover()
        elif command == "show":
            result = spool.get(request["message_id"])
        else:
            result = spool.list_messages(request.get("status"))
    except _CliError as exc:
        _emit({"ok": False, "error": {"code": exc.code, "message": exc.message, "details": exc.details}})
        return exc.exit_code
    except SpoolError as exc:
        _emit({"ok": False, "error": {"code": exc.code, "message": exc.message, "details": exc.details}})
        return 3 if exc.code in _EXIT_INTERNAL_CODES else 2
    except Exception:
        _emit(
            {
                "ok": False,
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": "unexpected internal failure",
                    "details": {},
                },
            }
        )
        return 3
    _emit({"ok": True, "result": result})
    return 0


if __name__ == "__main__":
    sys.exit(main())

